import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        int[][] dpArray = new int[n + 1][h + 1];

        // Initialize dpArray with -1
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= h; j++) {
                dpArray[i][j] = -1;
            }
        }

        dpArray[0][0] = 1;

        System.out.println(countTrees(n, h, dpArray));
        scanner.close();
    }

    private static int countTrees(int n, int h, int[][] dpArray) {
        if (dpArray[n][h] != -1) {
            return dpArray[n][h];
        }
        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            return countTrees(n, 1, dpArray);
        }

        int totalCount = 0;
        for (int i = 0; i < n; i++) {
            totalCount += countTrees(n - i - 1, 0, dpArray) * countTrees(i, h - 1, dpArray);
            totalCount += countTrees(n - i - 1, h - 1, dpArray) * countTrees(i, 0, dpArray);
            totalCount -= countTrees(n - i - 1, h - 1, dpArray) * countTrees(i, h - 1, dpArray);
        }

        dpArray[n][h] = totalCount;
        return totalCount;
    }
}
